mapper.update:
UPDATE gw_vehicle
   SET current_mileage = #{mileage}
 WHERE vehicle_id = #{vehicleId}
   AND current_mileage < #{mileage}

UPDATE gw_vehicle_reservation
   SET status_cd = 'COMPLETED', mileage_end = #{mileageEnd}
 WHERE reservation_id = #{reservationId}

mapper.select:
SELECT COUNT(*) FROM gw_vehicle_reservation
 WHERE deleted_at IS NULL
   AND status_cd IN ('PENDING','APPROVED','IN_USE')
   AND vehicle_id = #{vehicleId}
   AND end_dt > #{start} AND start_dt < #{end}
AND reservation_id <> #{excludeId}

SELECT 
  FROM gw_vehicle_reservation r
  JOIN gw_vehicle vh ON vh.vehicle_id = r.vehicle_id
  JOIN gw_user u ON u.user_id = r.user_id
 WHERE r.deleted_at IS NULL
   AND r.vehicle_id = #{vehicleId}
   AND r.start_dt < #{to}
   AND r.end_dt   > #{from}
 ORDER BY r.start_dt
